  #preview h1 { font-size: 1.7em; border-bottom: 2px solid var(--border); padding-bottom: .3em; }
  #preview h2 { font-size: 1.4em; }
  #preview h3 { font-size: 1.15em; }
  #preview code {
    background: var(--code-bg); padding: .15em .4em; border-radius: 4px;
    font-family: ui-monospace, Menlo, Consolas, monospace; font-size: .9em;
  }
  #preview pre {
    background: var(--code-bg); padding: 14px 16px; border-radius: 8px; overflow-x: auto;
  }
  #preview pre code { padding: 0; background: none; }
  #preview blockquote {
    margin: 0; padding-left: 16px; border-left: 3px solid var(--accent);
    color: var(--muted); font-style: italic;
  }
  #preview a { color: var(--accent); text-decoration: none; }
  #preview a:hover { text-decoration: underline; }
  #preview img { max-width: 100%; border-radius: 8px; }
  #preview hr { border: none; border-top: 1px solid var(--border); margin: 1.5em 0; }
  #preview table { border-collapse: collapse; width: 100%; }
  #preview th, #preview td { border: 1px solid var(--border); padding: 6px 10px; text-align: left; }
  #preview ul, #preview ol { padding-left: 1.4em; }
